'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['serializeSafeRow']);
assert.strictEqual(typeof api.serializeSafeRow, 'function');
const { serializeSafeRow } = api;

assert.strictEqual(serializeSafeRow([]), '');
assert.strictEqual(serializeSafeRow(['plain', '', 'two words']), 'plain,,two words');
assert.strictEqual(
  serializeSafeRow(['=SUM(A1:A2)', '+1', '-2', '@cmd', '  =x', '\t+run', '\r\n-3', ' safe']),
  "'=SUM(A1:A2),'+1,'-2,'@cmd,'  =x,'\t+run,\"'\r\n-3\", safe"
);
assert.strictEqual(
  serializeSafeRow(['a,b', 'say "hi"', 'line\nnext', 'carriage\rreturn']),
  '"a,b","say ""hi""","line\nnext","carriage\rreturn"'
);
assert.strictEqual(
  serializeSafeRow(['  @x,y', '\t="quoted"', '   ', 'x=1', "'=-already"]),
  '"\'  @x,y","\'\t=""quoted""",   ,x=1,\'=-already'
);

const cells = ['z', ' =formula', 'a,b'];
const snapshot = cells.slice();
assert.strictEqual(serializeSafeRow(cells), "z,' =formula,\"a,b\"");
assert.deepStrictEqual(cells, snapshot);

for (const invalid of [
  null,
  {},
  'a,b',
  [1],
  ['ok', null],
  ['ok', undefined],
  ['ok', new String('wrapped')]
]) {
  assert.throws(() => serializeSafeRow(invalid), TypeError);
}

